    "C03", "C08", "C09", "C12", "C23", "C24", "C01", "C21", "C25", "C32"
  ],
  "claims": [
    {
      "claim": "Direct absolute oral bioavailability measurements for structurally related cytidine/pyrimidine nucleoside analogs are all above the 20% threshold: zalcitabine 80% (54–127%) in fasted patients and 30% in fasted mice; lamivudine 69–93% across fasted patients and formulations; doxifluridine ~50–80% in patients and 34–47% as capsules.",
      "card_ids": ["C19", "C31", "C06", "C07", "C17", "C22", "C29", "C30", "C03", "C08", "C09", "C12", "C23", "C24"]
    },
    {
      "claim": "Other nucleoside analogs with reported high oral bioavailability include mericitabine (excellent in humans), islatravir (high, active at 0.5 mg weekly), and maribavir (good in animals/humans; estimates 30–50%).",
      "card_ids": ["C01", "C21", "C04", "C13", "C14", "C18", "C25", "C32"]
    },
    {
      "claim": "New L3 oral exposure records show rapid absorption and measurable systemic exposure after oral dosing of lamivudine (median Tmax 0.75–1.26 h; geometric mean Cmax 3.3 µg/mL at 300 mg; FDC/tablet AUC0-last ratio 0.99) and of oral uridine in mice (Cmax 20.1 µM, AUC 109 µmol·h·L−1), consistent with oral absorption of polar nucleosides.",
      "card_ids": ["C37", "C41", "C40", "C36"]
    },
    {
      "claim": "No supplied record reports an absolute oral bioavailability below 20% for any structurally related nucleoside; the lowest values observed (30–47%) remain above the threshold.",
      "card_ids": ["C31", "C32", "C23"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C35", "C36", "C37", "C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for decitabine (query) is present in the supplied records.",
    "No data on cytidine deaminase-mediated first-pass metabolism or acid stability of the 5-aza-triazinone ring are available in the cards or query prior.",
    "L3 records are for lamivudine and uridine, not decitabine; transfer from these analogs does not address the query's unique 5-aza modification and 2-deoxyribose scaffold.",
    "Physicochemical prior indicates unfavorable passive permeability; active transport and high solubility could compensate but remain unmeasured."
  ],
  "decision_summary": "Predicted high (F>=20%) because all transferable nucleoside analog records, including new L3 oral exposure data for lamivudine and uridine, show oral absorption and absolute bioavailability above 20% (lowest 30–47%), and no affirmative evidence supports F<20%. Confidence remains low because no direct decitabine PK data are available and the 5-aza modification may alter metabolism/stability."
}

